-- -------- linkguard_domains (#186 Link Guard scope) --------
-- Protected recipient domains for time-of-click safe-links. '_default' (if
-- present + enabled) applies Link Guard to every local recipient domain.
-- All other Link Guard config lives in parameters2 (module='linkguard');
-- the container's operational data (feeds, verdict cache, clicks) is in its
-- own SQLite, not here.
CREATE TABLE IF NOT EXISTS `linkguard_domains` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `domain` varchar(255) NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_domain` (`domain`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- -------- linkguard_url_rules (#186 admin allow/block) --------
-- Operator-curated URL rules pushed to the Link Guard container's verdict
-- pipeline. 'allow' forces CLEAN (trumps feeds/heuristics); 'block' forces
-- MALICIOUS. `pattern` is a host (covers subdomains) or host/path prefix.
CREATE TABLE IF NOT EXISTS `linkguard_url_rules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rule_type` enum('allow','block') NOT NULL,
  `pattern` varchar(512) NOT NULL,
  `note` varchar(255) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_rule` (`rule_type`,`pattern`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- -------- linkguard_abused_hosts (#278 abused/redirector hosts, seeded) --------
CREATE TABLE IF NOT EXISTS `linkguard_abused_hosts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `host` varchar(255) NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `note` varchar(255) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_abused_host` (`host`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ONE-TIME baseline seed (only when empty, so operator edits survive re-runs).
INSERT INTO `linkguard_abused_hosts` (`host`,`note`)
SELECT s.host, 'baseline' FROM (
              SELECT 'storage.googleapis.com'         AS host
    UNION ALL SELECT 'firebasestorage.googleapis.com'
    UNION ALL SELECT 'firebaseapp.com'
    UNION ALL SELECT 'web.app'
    UNION ALL SELECT 'appspot.com'
    UNION ALL SELECT 'googleusercontent.com'
    UNION ALL SELECT 'blob.core.windows.net'
    UNION ALL SELECT 's3.amazonaws.com'
    UNION ALL SELECT 'r2.dev'
    UNION ALL SELECT 'pages.dev'
    UNION ALL SELECT 'workers.dev'
    UNION ALL SELECT 'github.io'
    UNION ALL SELECT 'netlify.app'
    UNION ALL SELECT 'vercel.app'
    UNION ALL SELECT 'herokuapp.com'
    UNION ALL SELECT 'onrender.com'
    UNION ALL SELECT 'surge.sh'
    UNION ALL SELECT 'glitch.me'
    UNION ALL SELECT 'repl.co'
    UNION ALL SELECT 'replit.app'
    UNION ALL SELECT 'weebly.com'
    UNION ALL SELECT 'wixsite.com'
    UNION ALL SELECT '000webhostapp.com'
    UNION ALL SELECT 'trycloudflare.com'
    UNION ALL SELECT 'ngrok.io'
    UNION ALL SELECT 'ngrok-free.app'
) AS s
WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1 FROM `linkguard_abused_hosts` LIMIT 1) AS _g);

