-- 6 row(s) for `malware_feeds`
INSERT IGNORE INTO `malware_feeds` VALUES (1,'sanesecurity','no','15 */1 * * *',NULL,NULL,NULL,2,NULL,NULL,NULL,'Sanesecurity produces add-ons signatures to help improve the ClamAV detection rate on Zero-Day malware and even on Zero-Hour malware. Since 2006 they have provided professional quality ClamAV signatures to protect against the following email types: Macro malware, Zip malware, Rar malware, Javascript malware, 7z malware, Phishing, Spear phishing and other types of common emailed malware and spam. Sanesecurity 3rd Party ClamAV signatures can also help prevent TeslaCrypt, Cryptowall, Cryptolocker and other ransomware, where the source usually starts as a malicious email. Sanesecurity signatures are free, however we highly recommend donating to this worthwhile cause. More information can be found at http://sanesecurity.com/');
INSERT IGNORE INTO `malware_feeds` VALUES (2,'securiteinfo','no','15 */4 * * *','',NULL,NULL,2,NULL,'',NULL,'SecuriteInfo.com is a french computer security company. They provide state-of-the-art technologies to deliver security audits and products, like vulnerability audits for websites, network audits and firewall/proxy appliances. More information can be found at https://www.securiteinfo.com/');
INSERT IGNORE INTO `malware_feeds` VALUES (3,'linuxmalwaredetect','no','15 */8 * * *',NULL,NULL,NULL,2,NULL,NULL,NULL,'Linux Malware Detect (LMD) is a malware scanner for Linux released under the GNU GPLv2 license, that is designed around the threats faced in shared hosted environments. It uses threat data from network edge intrusion detection systems to extract malware that is actively being used in attacks and generates signatures for detection. In addition, threat data is also derived from user submissions with the LMD checkout feature and from malware community resources. The signatures that LMD uses are MD5 file hashes and HEX pattern matches, they are also easily exported to any number of detection tools such as ClamAV. More information can be found at https://www.rfxn.com/projects/linux-malware-detect/');
INSERT IGNORE INTO `malware_feeds` VALUES (4,'yararules','yes','15 */1 * * *',NULL,NULL,NULL,2,NULL,NULL,NULL,'This project covers the need of a group of IT Security Researches to have a single repository where different Yara signatures are compiled, classified and kept as up to date as possible, and begin as an open source community for collecting Yara rules. The Yara ruleset is under the GNU-GPLv2 license and open to any user or organization, as long as you use it under this license. More information can be found at https://github.com/Yara-Rules/rules');
INSERT IGNORE INTO `malware_feeds` VALUES (5,'malwarepatrol','false','15 */4 * * *','RECEIPT_NO','15','clamav_basic',2,'yes',NULL,NULL,'The Malware Patrol Project have been gathering and providing malware and ransomware threat data since 2005. This information is used by enterprises and open source members of their community to protect networks and assets in more than 130 countries. For ease of use, they offer data feeds in pre-defined and customized contents and formats compatible with the most popular security systems. More information can be found at https://www.malwarepatrol.net/');
INSERT IGNORE INTO `malware_feeds` VALUES (6,'urlhaus','yes','15 */4 * * *',NULL,NULL,NULL,2,NULL,NULL,NULL,'URLhaus is a project from abuse.ch with the goal of sharing malicious URLs that are being used for malware distribution https://urlhaus.abuse.ch/');

